"use strict";
// Loads its parts with a computed specifier (R1.2): a Node island. It
// also requires the CommonJS helper the native side uses.
const { createRequire } = require("node:module");
const once = createRequire(__filename)(["once", "like"].join(""));

class FileBlob {
  constructor(data) {
    this.data = data;
    this.mode = 0o644;
  }
}
exports.FileBlob = FileBlob;
exports.fromText = (text) => new FileBlob(text);
exports.fromBytes = (text) => new FileBlob(Buffer.from(text));
exports.onceTotal = (values) => {
  const sum = once(() => values.reduce((a, b) => a + b, 0));
  return sum() + sum();
};
